package workbench.generics.l08

import java.time.LocalDate

/*
 * Do not edit this file. It is the same in src/main and src/solution.
 *
 * An inline function is copied into each caller when the CALLER is compiled. That is what lets a
 * reified T become a real class at each call site. It also means a test that called asOrNull<String>()
 * directly would keep a copy of whatever asOrNull looked like when the test was compiled. So the tests
 * call these ordinary functions instead. They are compiled together with your code, so they always
 * contain a fresh copy of your inline functions.
 */
object Callers {
    fun stringOrNull(x: Any?): String? = x.asOrNull<String>()
    fun longOrNull(x: Any?): Long? = x.asOrNull<Long>()
    fun eventOrNull(x: Any?): PaymentEvent? = x.asOrNull<PaymentEvent>()

    fun cardsIn(items: List<Any?>): List<CardAuthorized> = instancesOf<CardAuthorized>(items)
    fun stringsIn(items: List<Any?>): List<String> = instancesOf<String>(items)

    fun money(parsers: Parsers, text: String): Money = parsers.parse<Money>(text)
    fun date(parsers: Parsers, text: String): LocalDate = parsers.parse<LocalDate>(text)
}
